/* Real kqueue(2)/kevent(2) smoketest -- Phase 6.6 (libdispatch prereqs,
 * docs/daemon-roadmap.md) needs "real kqueue/kevent in userland" before
 * a real dispatch source engine can be built; this project's raw syscall
 * stubs for both (_kevent/_kqueue, generated by the same real
 * create-syscalls.pl pass every other tier uses) have been compiled and
 * linked into every tools/userland_staging/build_simple_cmds.sh binary
 * since that script's SYS_STUBS_NEEDED list added them, but never
 * exercised end to end -- this is that missing real functional proof.
 *
 * Uses EVFILT_TIMER (real, unmodified third_party/xnu-7195/bsd/kern/
 * kern_event.c:316 registers a real timer_filtops for it) rather than an
 * I/O-backed filter, deliberately: it needs no second fd/pipe/socket
 * dependency, keeping this smoketest's own dependency surface to just
 * kqueue()+kevent(), not a proxy test of pipe()/socket() as well.
 *
 * Real pass criteria: kqueue() returns a valid fd, EV_SET+kevent()
 * registers a one-shot 50ms timer with zero errors, and a second
 * kevent() call (blocking, no timeout) returns exactly one real event
 * whose ident/filter match what was registered.
 *
 * REAL, SEPARATE GAP FOUND WHILE VERIFYING THIS (2026-08-25, QEMU,
 * qemu/hfs_root_test.img): the first version of this smoketest used
 * printf() for its FAIL/PASS output and crashed (SIGSEGV, real kernel
 * "Failed to send exception EXC_CORPSE_NOTIFY" message) with zero
 * console output at all -- looked at first like a crash inside
 * kqueue()/kevent() themselves, or even before main(). Bisected with
 * raw write(2) diagnostics (see diag() below, which bypasses stdio
 * entirely) and confirmed real kqueue()/kevent() both return correctly
 * every time -- the crash is really inside printf() itself, specific to
 * this smoketest's own minimal build_kqueue_smoketest.sh link recipe
 * (simpler than e.g. build_libc_printf.sh's own working
 * libc_printf_smoketest.macho link -- some real, not-yet-identified
 * difference in the linked object/archive set breaks printf's
 * buffered-stdio path here). Real, separate, undiagnosed gap -- not
 * chased further in this pass since it's orthogonal to what this
 * smoketest exists to prove; this file uses raw write(2) (diag() below)
 * for all its own output as a real, honest workaround, not a fix.
 */
#include <sys/types.h>
#include <sys/event.h>
#include <sys/time.h>
#include <unistd.h>
#include <string.h>

/* Raw write(2), not printf() -- see the real, separate printf() crash
 * documented above. */
static void diag(const char *s)
{
	write(2, s, strlen(s));
}

int main(void)
{
	diag("DIAG: entered main\n");
	int kq = kqueue();
	diag("DIAG: kqueue() returned\n");
	if (kq < 0) {
		diag("FAIL: kqueue() failed\n");
		return 1;
	}

	struct kevent chg;
	EV_SET(&chg, 1 /* ident */, EVFILT_TIMER, EV_ADD | EV_ONESHOT, 0,
	    50 /* ms */, NULL);
	diag("DIAG: about to call kevent()\n");

	struct kevent evt;
	memset(&evt, 0, sizeof(evt));

	/* Register + immediately wait for it in one call, real Apple
	 * kevent() semantics (changelist processed before the wait). */
	int n = kevent(kq, &chg, 1, &evt, 1, NULL);
	diag("DIAG: kevent() returned\n");
	if (n < 0) {
		diag("FAIL: kevent() register/wait failed\n");
		close(kq);
		return 1;
	}
	if (n != 1) {
		diag("FAIL: kevent() returned wrong event count\n");
		close(kq);
		return 1;
	}
	if (evt.ident != 1 || evt.filter != EVFILT_TIMER) {
		diag("FAIL: unexpected event ident/filter\n");
		close(kq);
		return 1;
	}

	close(kq);
	diag("PASS: real kqueue()/kevent() EVFILT_TIMER round-trip\n");
	return 0;
}
